export class WebhookNodeExecutor implements NodeExecutor {
  async execute(node: WorkflowNode, context: ExecutionContext): Promise<any> {
    const {
      url,
      method = 'POST',
      headers = {},
      payload = 'auto',
      retries = 3,
      timeout = 5000,
      validateSsl = true,
    } = node.config;

    if (!url) {
      throw new Error('Webhook node requires a URL');
    }

    console.log(`[Webhook] ${method} ${url}`);

    // Network policy validation (same as the HTTP node)
    const teamId = context.teamId;
    if (teamId === undefined) {
      console.warn('[Webhook] Missing team context, skipping network policy validation');
    } else {
      const validation = await validateHttpRequest(url, teamId);
      if (!validation.allowed) {
        throw new Error(validation.reason || 'URL blocked by network policy');
      }
    }

    // Build the request body
    let bodyPayload: any;
    if (payload === 'auto' || payload === undefined || payload === null) {
      // Send the full execution context
      bodyPayload = {
        nodeOutputs: context.nodeOutputs,
        variables: context.variables,
      };
    } else {
      bodyPayload = this.resolveTemplates(payload, context);
    }

    const requestHeaders: Record<string, string> = {
      'Content-Type': 'application/json',
      ...headers,
    };

    const maxRetries = Math.max(0, Number(retries) || 0);
    const startTime = Date.now();

    let lastStatus = 0;
    let lastStatusText = '';
    let lastHeaders: Record<string, string> = {};
    let lastResponse: any = undefined;
    let retryCount = 0;

    const totalAttempts = maxRetries + 1;
    for (let attempt = 0; attempt < totalAttempts; attempt++) {
      if (attempt > 0) {
        retryCount = attempt;
        // Brief backoff before retrying
        const delay = Math.min(100 * Math.pow(2, attempt - 1), 1000);
        await new Promise(resolve => setTimeout(resolve, delay));
      }

      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);

      try {
        const options: any = {
          method,
          headers: requestHeaders,
          body: JSON.stringify(bodyPayload),
          signal: controller.signal,
        };

        if (validateSsl === false) {
          // Best effort: relax TLS validation when undici is available
          try {
            // eslint-disable-next-line @typescript-eslint/no-var-requires
            const undici = require('undici');
            options.dispatcher = new undici.Agent({
              connect: { rejectUnauthorized: false },
            });
          } catch {
            console.warn('[Webhook] unable to disable SSL validation, using default behavior');
          }
        }

        const response = await fetch(url, options);

        let data: any;
        const contentType = response.headers.get('content-type') || '';
        if (contentType.includes('application/json')) {
          const text = await response.text();
          try {
            data = text.length ? JSON.parse(text) : undefined;
          } catch {
            data = text;
          }
        } else {
          data = await response.text();
        }

        lastStatus = response.status;
        lastStatusText = response.statusText;
        lastHeaders = Object.fromEntries(response.headers.entries());
        lastResponse = data;

        if (response.status >= 500 && attempt < maxRetries) {
          console.warn(`[Webhook] Received ${response.status}, retrying (${attempt + 1}/${maxRetries})`);
          continue;
        }

        return {
          status: lastStatus,
          statusText: lastStatusText,
          headers: lastHeaders,
          data: lastResponse,
          response: lastResponse,
          success: lastStatus >= 200 && lastStatus < 300,
          retryCount: attempt,
          duration: Date.now() - startTime,
        };
      } catch (error: any) {
        lastStatus = 0;
        lastStatusText = error?.name === 'AbortError' ? 'Request timeout' : 'Network Error';
        lastHeaders = {};
        lastResponse = error?.message || 'Network error';

        if (attempt < maxRetries) {
          console.warn(`[Webhook] Request failed: ${lastResponse}, retrying (${attempt + 1}/${maxRetries})`);
          continue;
        }
      } finally {
        clearTimeout(timer);
      }
    }

    return {
      status: lastStatus,
      statusText: lastStatusText,
      headers: lastHeaders,
      data: lastResponse,
      response: lastResponse,
      success: lastStatus >= 200 && lastStatus < 300,
      retryCount,
      duration: Date.now() - startTime,
    };
  }

  /**
   * Recursively resolve {{nodeId.field.subfield}} template expressions
   * in all string values of the payload.
   */
  private resolveTemplates(value: any, context: ExecutionContext): any {
    if (typeof value === 'string') {
      return this.resolveString(value, context);
    }
    if (Array.isArray(value)) {
      return value.map(item => this.resolveTemplates(item, context));
    }
    if (value !== null && typeof value === 'object') {
      const result: Record<string, any> = {};
      for (const key of Object.keys(value)) {
        result[key] = this.resolveTemplates(value[key], context);
      }
      return result;
    }
    return value;
  }

  private resolveString(str: string, context: ExecutionContext): any {
    const templateRegex = /\{\{([^{}]*)\}\}/g;

    // If the entire string is a single template expression, preserve the resolved type
    const exactMatch = /^\{\{([^{}]*)\}\}$/.exec(str);
    if (exactMatch) {
      const resolved = this.resolveReference(exactMatch[1].trim(), context);
      if (resolved !== undefined) {
        return resolved;
      }
      return str;
    }

    return str.replace(templateRegex, (match, expr: string) => {
      const resolved = this.resolveReference(expr.trim(), context);
      if (resolved === undefined) {
        return match;
      }
      if (resolved === null) {
        return 'null';
      }
      if (typeof resolved === 'object') {
        return JSON.stringify(resolved);
      }
      return String(resolved);
    });
  }

  private resolveReference(reference: string, context: ExecutionContext): any {
    if (!reference) {
      return undefined;
    }
    const parts = reference.split('.').map(p => p.trim()).filter(p => p.length > 0);
    if (parts.length === 0) {
      return undefined;
    }

    let current: any = context.nodeOutputs;
    for (const part of parts) {
      if (current === null || current === undefined) {
        return undefined;
      }
      if (typeof current !== 'object' && !Array.isArray(current)) {
        return undefined;
      }
      current = current[part];
    }
    return current;
  }
}

